-- Group ids are UUIDv7 generated by the database (ADR 0007), in the groups table and in every column that holds one.
-- Ids handed out so far become fixed UUIDs: 0197a001-0000-7000-8000-<id>.
ALTER TABLE group_membership DROP CONSTRAINT group_membership_group_id_fkey;

ALTER TABLE groups ALTER COLUMN id DROP IDENTITY;
ALTER TABLE groups ALTER COLUMN id TYPE UUID
    USING ('0197a001-0000-7000-8000-' || lpad(id::text, 12, '0'))::uuid;
ALTER TABLE groups ALTER COLUMN id SET DEFAULT uuidv7();

ALTER TABLE group_membership ALTER COLUMN group_id TYPE UUID
    USING ('0197a001-0000-7000-8000-' || lpad(group_id::text, 12, '0'))::uuid;
ALTER TABLE group_membership
    ADD CONSTRAINT group_membership_group_id_fkey FOREIGN KEY (group_id) REFERENCES groups (id);

-- No foreign key from event: groups and events are different modules.
ALTER TABLE event ALTER COLUMN group_id TYPE UUID
    USING ('0197a001-0000-7000-8000-' || lpad(group_id::text, 12, '0'))::uuid;
